file_put_contents($dir.'chemistry-equation-balancer.blade.php',t('fas fa-equals','Chemistry Equation Balancer','Balance chemical reactions with step-by-step breakdown','<div class="row g-3"><div class="col-12"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Chemical Equation</label><input type="text" id="in-eq" class="form-control form-control-lg" value="Fe + O2 = Fe2O3" placeholder="e.g. Fe + O2 = Fe2O3"></div><div class="col-12"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="in-step" checked><label class="form-check-label small fw-bold text-secondary" for="in-step">Show Steps</label></div></div></div>','<b>Law of Conservation of Mass:</b> atoms must be equal on both sides','document.addEventListener("DOMContentLoaded",function(){function parse(c){var e={},re=/([A-Z][a-z]?)(\d*)/g,m;while((m=re.exec(c))!==null)if(m[1])e[m[1]]=(e[m[1]]||0)+parseInt(m[2]||"1");return e;}function balance(eq){eq=eq.replace(/→/g,"=").replace(/->/g,"=");var s=eq.split("=");if(s.length!==2)return null;var R=s[0].split("+").map(function(x){return x.trim();}).filter(Boolean);var P=s[1].split("+").map(function(x){return x.trim();}).filter(Boolean);var all=R.concat(P),n=all.length,parsed=all.map(parse);var els=new Set();parsed.forEach(function(p){for(var e in p)els.add(e);});els=[...els];function tryB(max){function chk(c){for(var ei=0;ei<els.length;ei++){var el=els[ei],l=0,r=0;for(var i=0;i<R.length;i++)l+=c[i]*(parsed[i][el]||0);for(var i=0;i<P.length;i++)r+=c[R.length+i]*(parsed[R.length+i][el]||0);if(l!==r)return false;}return true;}function en(idx,cur){if(idx===n)return chk(cur)?cur.slice():null;for(var c=1;c<=max;c++){cur[idx]=c;var r=en(idx+1,cur);if(r)return r;}return null;}return en(0,new Array(n).fill(1));}var co=tryB(n<=4?15:10);if(!co)return null;var rp=[],pp=[];for(var i=0;i<R.length;i++)rp.push((co[i]>1?co[i]:"")+R[i]);for(var i=0;i<P.length;i++)pp.push((co[R.length+i]>1?co[R.length+i]:"")+P[i]);return{balanced:rp.join(" + ")+" → "+pp.join(" + "),coeffs:co,R:R,P:P,els:els};}document.getElementById("btn-calc").addEventListener("click",function(){var eq=document.getElementById("in-eq").value.trim();if(!eq)return;var r=balance(eq);if(!r){document.getElementById("out-main").textContent="Could not balance";document.getElementById("out-unit").textContent="Check format";document.getElementById("out-ins").innerHTML="<p class=\\"text-danger\\">Use format: A + B = C + D</p>";}else{document.getElementById("out-main").textContent=r.balanced;document.getElementById("out-main").style.fontSize="1.5rem";document.getElementById("out-unit").textContent="Balanced";document.getElementById("out-detail").innerHTML=\'<div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Reactants</div><div class="h5 fw-bold mb-0 text-primary">\'+r.R.length+\'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Products</div><div class="h5 fw-bold mb-0 text-info">\'+r.P.length+\'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Elements</div><div class="h5 fw-bold mb-0 text-success">\'+r.els.length+\'</div></div></div>\';var ins=["Coefficients: ["+r.coeffs.join(", ")+"]","Atoms balanced on both sides ✓"];document.getElementById("out-ins").innerHTML=\'<ul class="list-unstyled mb-0">\'+ins.map(function(x){return\'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>\'+x+"</li>";}).join("")+"</ul>";}document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-eq").value="Fe + O2 = Fe2O3";document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText(document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\\"fas fa-copy me-1\\"></i>Copy";},2e3);});});'));
