file_put_contents($dir.'solution-dilution-calc.blade.php',t('fas fa-fill-drip','Solution Dilution Calc','Calculate dilution using C₁V₁ = C₂V₂','<div class="row g-3"><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">C₁ (M)</label><input type="number" id="in-c1" class="form-control form-control-lg" value="1" step="0.01"></div><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">V₁ (mL)</label><input type="number" id="in-v1" class="form-control form-control-lg" value="" placeholder="?" step="0.1"></div><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">C₂ (M)</label><input type="number" id="in-c2" class="form-control form-control-lg" value="0.1" step="0.01"></div><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">V₂ (mL)</label><input type="number" id="in-v2" class="form-control form-control-lg" value="500" step="0.1"></div></div>','<b>Formula:</b> C₁V₁ = C₂V₂ — leave one field empty to solve','document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var c1=document.getElementById("in-c1").value,v1=document.getElementById("in-v1").value,c2=document.getElementById("in-c2").value,v2=document.getElementById("in-v2").value;var r,lbl;if(!v1&&c1&&c2&&v2){r=(parseFloat(c2)*parseFloat(v2))/parseFloat(c1);lbl="V₁ = "+r.toFixed(2)+" mL";}else if(!c1&&v1&&c2&&v2){r=(parseFloat(c2)*parseFloat(v2))/parseFloat(v1);lbl="C₁ = "+r.toFixed(4)+" M";}else if(!c2&&c1&&v1&&v2){r=(parseFloat(c1)*parseFloat(v1))/parseFloat(v2);lbl="C₂ = "+r.toFixed(4)+" M";}else if(!v2&&c1&&v1&&c2){r=(parseFloat(c1)*parseFloat(v1))/parseFloat(c2);lbl="V₂ = "+r.toFixed(2)+" mL";}else{document.getElementById("out-main").textContent="Leave one field empty";return;}document.getElementById("out-main").textContent=r.toFixed(4);document.getElementById("out-unit").textContent=lbl;document.getElementById("out-ins").innerHTML="<p>C₁V₁ = C₂V₂ solved: <b>"+lbl+"</b></p>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-c1").value=1;document.getElementById("in-v1").value="";document.getElementById("in-c2").value=0.1;document.getElementById("in-v2").value=500;document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText(document.getElementById("out-unit").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\\"fas fa-copy me-1\\"></i>Copy";},2e3);});});'));
